import itertools

def calculate_energy(seq):
    n = len(seq)
    energy = 0
    for k in range(1, n):
        ck = sum(seq[i] * seq[i+k] for i in range(n-k))
        energy += ck**2
    return energy

def solve():
    n = 21
    fixed = {5: -1, 12: -1, 17: 1, 20: 1}

    # Indices that are not fixed
    free_indices = [i for i in range(n) if i not in fixed]

    for p in itertools.product([-1, 1], repeat=len(free_indices)):
        seq = [0] * n
        for i, val in fixed.items():
            seq[i] = val
        for i, val in zip(free_indices, p):
            seq[i] = val

        if calculate_energy(seq) <= 52:
            return seq
    return None

result = solve()
print(result)
